const STORAGE='youshu-v1';
const $=id=>document.getElementById(id);
const escapeHTML=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state={index:0,answers:{}},factor=1,calculated=null;
try{const stored=JSON.parse(localStorage.getItem(STORAGE));if(stored&&Number.isInteger(stored.index)&&stored.index>=0&&stored.index<10&&stored.answers&&typeof stored.answers==='object'){state.index=stored.index;for(const [k,v]of Object.entries(stored.answers)){if(/^\d$/.test(k)&&typeof v==='number'&&Number.isFinite(v)&&v>0&&v<=1e15)state.answers[k]=v}}}catch{}
function save(){try{localStorage.setItem(STORAGE,JSON.stringify(state))}catch{}}
function notify(message){$('toast').textContent=message;$('toast').classList.add('visible');clearTimeout(notify.timer);notify.timer=setTimeout(()=>$('toast').classList.remove('visible'),2600)}
function number(n){if(n>0&&n<0.001)return n.toExponential(2);if(n>=1e8)return `${new Intl.NumberFormat('zh-CN',{maximumFractionDigits:2}).format(n/1e8)} 亿`;if(n>=10000)return `${new Intl.NumberFormat('zh-CN',{maximumFractionDigits:2}).format(n/10000)} 万`;return new Intl.NumberFormat('zh-CN',{maximumFractionDigits:n<10?3:2}).format(n)}
function parseGuess(raw,multiplier=1){const normalized=String(raw).normalize('NFKC').replace(/[\s,，]/g,'');const m=normalized.match(/^((?:\d+(?:\.\d*)?|\.\d+)(?:e[+-]?\d+)?)(千|万|亿)?$/i);if(!m)throw new Error('请输入正数，可加“千、万、亿”，例如 0.78 万。');const n=Number(m[1])*(m[2]?{'千':1000,'万':10000,'亿':1e8}[m[2]]:multiplier);if(!Number.isFinite(n)||n<=0||n>1e15)throw new Error('请输入大于 0、且不超过 1,000 万亿的数。');return n}
function errorRatio(q,n){return n<q.min?q.min/n:n>q.max?n/q.max:1}
function score(n){return n>999?number(n)+'×':n.toFixed(2)+'×'}
function setIndex(index){if(!Number.isInteger(index)||index<0||index>=10)throw new Error('题号必须是 1 到 10。');state.index=index;factor=1;save();render()}
function submitGuess(raw,multiplier=1){if(state.answers[state.index]!=null)throw new Error('这道题已锁定猜测。');const value=parseGuess(raw,multiplier);state.answers[state.index]=value;save();render();return{question:state.index+1,guess:value,ratio:errorRatio(QUESTIONS[state.index],value)}}
function scaleChart(q,guess){const lo=Math.log10(Math.min(q.min,guess))-0.55,hi=Math.log10(Math.max(q.max,guess))+0.55;const x=n=>35+(Math.log10(n)-lo)/(hi-lo)*430;const gx=x(guess),ax=x(q.answer),same=Math.abs(gx-ax)<50;return `<div class="scale"><div class="scale-caption"><span>你的猜测与参考答案</span><span>对数刻度</span></div><svg viewBox="0 0 500 94" role="img" aria-label="猜测 ${number(guess)}，参考答案 ${q.display}"><line x1="35" y1="47" x2="465" y2="47" stroke="#dae1d3" stroke-width="6" stroke-linecap="round"/>${q.min!==q.max?`<line x1="${x(q.min)}" y1="47" x2="${x(q.max)}" y2="47" stroke="#bdd67a" stroke-width="10"/>`:''}<line x1="${ax}" y1="36" x2="${ax}" y2="60" stroke="#829b46" stroke-width="2"/><text x="${ax}" y="82" fill="#657b48" text-anchor="middle" font-size="12">参考 ${escapeHTML(q.display)}</text><circle cx="${gx}" cy="47" r="6" fill="#26392f"/><text x="${gx}" y="${same?19:25}" fill="#26392f" text-anchor="middle" font-size="12">你猜 ${escapeHTML(number(guess))}</text></svg></div>`}
function render(){const q=QUESTIONS[state.index],guess=state.answers[state.index],count=Object.keys(state.answers).length;document.title=`有数 · ${q.short}`;$('progress-label').textContent=`QUESTION ${String(state.index+1).padStart(2,'0')} / 10`;$('progress-fill').style.width=`${count*10}%`;$('question-nav').innerHTML=QUESTIONS.map((item,i)=>`<button class="nav-item ${i===state.index?'current':''} ${state.answers[i]!=null?'answered':''}" data-index="${i}" aria-label="第 ${i+1} 题：${escapeHTML(item.short)}${state.answers[i]!=null?'，已作答':''}" ${i===state.index?'aria-current="step"':''}>${String(i+1).padStart(2,'0')}</button>`).join('');$('question-nav').querySelectorAll('button').forEach(b=>b.onclick=()=>setIndex(Number(b.dataset.index)));
const top=`<div class="card-top"><span class="category">${q.category}</span><span class="question-number">${String(state.index+1).padStart(2,'0')}</span></div>`;
if(guess==null){$('game').innerHTML=`<article class="question-card">${top}<h2 class="question-title">${q.title}</h2><p class="conditions">${q.condition}</p><form id="guess-form" novalidate><label class="guess-label" for="guess">你的猜测</label><div class="guess-box"><input id="guess" class="guess-input" placeholder="大胆猜个数" inputmode="decimal" autocomplete="off" aria-describedby="guess-error"><span class="unit-label">${q.unit}</span></div><div class="input-help"><span>支持数字、千、万、亿</span><div class="unit-chips"><button type="button" class="unit-chip active" data-factor="1">原数</button><button type="button" class="unit-chip" data-factor="10000">万</button><button type="button" class="unit-chip" data-factor="100000000">亿</button></div></div><button class="primary-button lock-button" type="submit">锁定猜测<span class="key-hint">ENTER ↵</span></button><p id="guess-error" class="error" role="alert"></p></form><p class="card-note">一次猜测。没有标准的思考方式。</p></article>`;$('guess-form').onsubmit=e=>{e.preventDefault();try{submitGuess($('guess').value,factor)}catch(err){$('guess-error').textContent=err.message;$('guess').setAttribute('aria-invalid','true')}};document.querySelectorAll('.unit-chip').forEach(b=>b.onclick=()=>{factor=Number(b.dataset.factor);document.querySelectorAll('.unit-chip').forEach(c=>c.classList.toggle('active',c===b));$('guess').focus()})}
else{const ratio=errorRatio(q,guess),within=ratio===1,verdict=within?'正好落在答案范围内':guess<q.min?'猜小了一点':'猜大了一点';const encouragement=within?'这次很有数。':ratio<=2?'已经抓住了这个世界的尺度。':ratio<=10?'方向有了，再找一个参照。':'世界比直觉更出乎意料。';const next=QUESTIONS.findIndex((_,i)=>i>state.index&&state.answers[i]==null);const any=QUESTIONS.findIndex((_,i)=>state.answers[i]==null);$('game').innerHTML=`<article class="question-card reveal">${top}<h2 class="reveal-question">${q.title}</h2><div class="result-values"><div><small>你的猜测</small><strong>${number(guess)}</strong><span>${q.unit}</span></div><div><small>参考答案</small><strong>${q.display}</strong><span>${q.unit}</span></div></div><div class="score-panel"><div><p>${verdict}</p><small>${encouragement}</small></div><b>${score(ratio)}</b></div>${scaleChart(q,guess)}<section class="explanation"><h3>换个角度，原来如此</h3><p>${q.explanation}</p><p class="math-line">${q.math}</p><p>${q.after}</p><a class="source-link" href="${q.url}" target="_blank" rel="noopener noreferrer">查看答案依据</a></section><button class="primary-button next-button" id="next-question">${any<0?'查看全部成绩':'继续下一道'}</button></article>`;$('next-question').onclick=()=>{if(any<0)showSummary();else{setIndex(next>=0?next:any);$('game').scrollIntoView({block:'start',behavior:'smooth'})}}}
$('calculator-button').disabled=guess!=null;
}
function summaryText(){const entries=Object.entries(state.answers);if(!entries.length)return'有数 · 我准备来猜世界的另一种尺度。';const average=entries.reduce((s,[i,n])=>s+errorRatio(QUESTIONS[i],n),0)/entries.length;return`有数 · 试玩题册 VOL.001\n已答 ${entries.length}/10 题 · 平均误差 ${score(average)}\n${QUESTIONS.map((q,i)=>state.answers[i]!=null?`${String(i+1).padStart(2,'0')} ${q.short} ${score(errorRatio(q,state.answers[i]))}`:`${String(i+1).padStart(2,'0')} 待挑战`).join('\n')}\n凭感觉，也有数。`}
function showSummary(){const entries=Object.entries(state.answers),count=entries.length,avg=count?entries.reduce((s,[i,n])=>s+errorRatio(QUESTIONS[i],n),0)/count:0;const complete=count===10;$('summary-content').innerHTML=`<span class="eyebrow">YOUR ESTIMATION REPORT</span><h2>${complete?'十种尺度，你猜完了。':'每一次猜测，都有收获。'}</h2><div class="summary-score"><span class="eyebrow">VOL.001 · ${count} / 10 已完成</span><strong>${count?score(avg):'—'}</strong><p>${count?'你的平均误差 · 越接近 1× 越好':'先猜一道题，开启你的成绩单。'}</p></div>${QUESTIONS.map((q,i)=>`<div class="summary-row"><span>${String(i+1).padStart(2,'0')}</span><span>${q.short}</span><b>${state.answers[i]!=null?score(errorRatio(q,state.answers[i])):'待挑战'}</b></div>`).join('')}<div class="summary-actions"><button class="primary-button" id="save-card" ${count?'':'disabled'}>保存成绩卡</button><button class="secondary-button" id="copy-score" ${count?'':'disabled'}>复制成绩</button>${!complete?'<button class="secondary-button" id="continue-game">继续挑战</button>':''}</div><p class="small-note">成绩保存在当前设备。本试玩版不展示玩家排名。</p><button class="text-button" id="reset-button">重新挑战这十道题</button>`;$('save-card').onclick=downloadCard;$('copy-score').onclick=copyScore;if(!complete)$('continue-game').onclick=()=>{$('summary-dialog').close();setIndex(QUESTIONS.findIndex((_,i)=>state.answers[i]==null))};$('reset-button').onclick=()=>{$('summary-dialog').close();$('reset-dialog').showModal()};if(!$('summary-dialog').open)$('summary-dialog').showModal()}
async function copyScore(){try{await navigator.clipboard.writeText(summaryText());notify('成绩已复制')}catch{const el=document.createElement('textarea');el.value=summaryText();document.body.append(el);el.select();const ok=document.execCommand('copy');el.remove();notify(ok?'成绩已复制':'复制未成功，请使用成绩卡分享')}}
async function downloadCard(){const count=Object.keys(state.answers).length;if(!count)return;const canvas=document.createElement('canvas');canvas.width=1080;canvas.height=1540;const c=canvas.getContext('2d');c.fillStyle='#f4f5ef';c.fillRect(0,0,1080,1540);c.fillStyle='#26392f';c.fillRect(70,70,84,84);c.fillStyle='#ddf579';c.font='76px Georgia';c.fillText('≈',79,132);c.fillStyle='#26392f';c.font='bold 44px "PingFang SC",sans-serif';c.fillText('有数',177,128);c.font='20px sans-serif';c.fillText('YOUSHU  /  VOL.001',710,125);c.font='58px "Songti SC",serif';c.fillText('凭感觉，也有数。',70,244);c.fillStyle='#26392f';c.fillRect(70,302,940,285);const avg=Object.entries(state.answers).reduce((s,[i,n])=>s+errorRatio(QUESTIONS[i],n),0)/count;c.fillStyle='#ddf579';c.font='100px Georgia';c.fillText(score(avg),105,462,860);c.fillStyle='#fffef9';c.font='27px sans-serif';c.fillText(`平均误差  ·  ${count}/10 题已完成`,110,531);let y=660;QUESTIONS.forEach((q,i)=>{c.fillStyle='#718074';c.font='26px Georgia';c.fillText(String(i+1).padStart(2,'0'),75,y);c.fillStyle='#26392f';c.font='28px "PingFang SC",sans-serif';c.fillText(q.short,135,y);c.textAlign='right';c.font='27px Georgia';c.fillText(state.answers[i]!=null?score(errorRatio(q,state.answers[i])):'—',1000,y);c.textAlign='left';c.strokeStyle='#d9ded4';c.beginPath();c.moveTo(70,y+25);c.lineTo(1010,y+25);c.stroke();y+=67});c.fillStyle='#718074';c.font='24px "PingFang SC",sans-serif';c.fillText('用好奇心，丈量日常。',70,1425);c.font='20px sans-serif';c.fillText('成绩越接近 1× 越好 · 十道中文趣味估算题',70,1470);canvas.toBlob(blob=>{if(!blob){notify('生成失败，请复制成绩');return}const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='有数-我的估算成绩.png';a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);notify('成绩卡已生成，可从下载中保存')},'image/png')}
function calculate(expression){const clean=String(expression).normalize('NFKC').replace(/×/g,'*').replace(/[÷]/g,'/').replace(/[−–]/g,'-').replace(/\s/g,'');const tokens=clean.match(/(?:\d+(?:\.\d*)?|\.\d+)(?:e[+-]?\d+)?|[()+*/-]/gi);if(!tokens||tokens.join('')!==clean||tokens.length>200)throw new Error('请使用数字、加减乘除和括号。');let p=0;const primary=()=>{const t=tokens[p++];if(t==='+'||t==='-')return(t==='-'?-1:1)*primary();if(t==='('){const n=addition();if(tokens[p++]!==')')throw new Error('括号没有配对。');return n}if(t==null||!/^\d|^\./.test(t))throw new Error('计算式还不完整。');return Number(t)};const product=()=>{let n=primary();while(tokens[p]==='*'||tokens[p]==='/'){const op=tokens[p++],v=primary();if(op==='/'&&v===0)throw new Error('不能除以 0。');n=op==='*'?n*v:n/v}return n};const addition=()=>{let n=product();while(tokens[p]==='+'||tokens[p]==='-'){const op=tokens[p++],v=product();n=op==='+'?n+v:n-v}return n};const n=addition();if(p!==tokens.length||!Number.isFinite(n))throw new Error('请检查计算式。');return n}
function runCalculation(){try{calculated=calculate($('calculation').value);$('calculation-result').textContent='= '+new Intl.NumberFormat('zh-CN',{maximumFractionDigits:8}).format(calculated)}catch(e){calculated=null;$('calculation-result').textContent=e.message}return calculated}
$('help-button').onclick=()=>$('help-dialog').showModal();$('summary-button').onclick=showSummary;$('header-summary-button').onclick=showSummary;$('calculator-button').onclick=()=>{$('calculator-dialog').showModal();$('calculation').focus()};$('calculate-button').onclick=runCalculation;$('calculation').addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();runCalculation()}});$('use-calculation').onclick=()=>{const n=runCalculation();if(n==null)return;if(n<=0||n>1e15){$('calculation-result').textContent='猜测需要大于 0，且不超过 1,000 万亿。';return}$('calculator-dialog').close();if($('guess')){factor=1;document.querySelectorAll('.unit-chip').forEach(c=>c.classList.toggle('active',c.dataset.factor==='1'));$('guess').value=Number(n.toPrecision(12)).toString();$('guess').focus()}};
document.querySelectorAll('.dialog-close,.dialog-dismiss').forEach(b=>b.onclick=()=>b.closest('dialog').close());document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}}));$('confirm-reset').onclick=()=>{state={index:0,answers:{}};factor=1;save();$('reset-dialog').close();render();notify('新一轮挑战开始')};render();
// Structured browser tools use the same state and actions as the game.
if(document.modelContext?.registerTool){const lifecycle=new AbortController();const tools=[{name:'read_estimation_progress',description:'Read current question and device-local progress. Answer values are revealed only after a guess is submitted.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({question:state.index+1,title:QUESTIONS[state.index].title,unit:QUESTIONS[state.index].unit,completed:Object.keys(state.answers).length,submitted:state.answers[state.index]!=null})},{name:'navigate_estimation_question',description:'Open one of the ten questions without submitting a guess.',inputSchema:{type:'object',properties:{question:{type:'integer',minimum:1,maximum:10}},required:['question'],additionalProperties:false},execute:input=>{setIndex(input.question-1);return{question:state.index+1,submitted:state.answers[state.index]!=null}}},{name:'submit_estimation_guess',description:'Lock a positive numeric guess for the current unanswered question and reveal its explanation. This saves progress on this device.',inputSchema:{type:'object',properties:{guess:{type:'string'}},required:['guess'],additionalProperties:false},execute:input=>submitGuess(input.guess)}];for(const tool of tools){try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{})}catch{}}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true})}
